<script module lang="ts">
/**
 * An inline numbered link to a source, with a hover preview (`design/components/citation.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/citation.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/citation.module.css'
import HoverCard from '../overlays/HoverCard.svelte'
import type { CitationSource } from './SourceList.svelte'

export interface CitationProps {
  /**
   * The mark's one-based number in the reply's SourceList.
   */
  index: number
  /**
   * The source the mark refers to, whose `href` is the link target.
   */
  source: CitationSource
}
</script>

<script lang="ts">
let { index, source }: CitationProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#snippet contentOfHoverCard1()
    }<span class={styles.preview}
      ><span class={styles.previewTitle}>{source.title}</span
      >{#if source.domain !== undefined
        }<span class={styles.previewDomain}>{source.domain}</span
      >{/if
      }{#if source.snippet !== undefined
        }<span class={styles.previewSnippet}>{source.snippet}</span
      >{/if
    }</span
  >{/snippet
  }<HoverCard content={contentOfHoverCard1}
    ><a
      class={styles.mark}
      href={source.href}
      target="_blank"
      rel="noreferrer"
      aria-label={`${index}. ${source.title}`}
      data-member="citation"
      >{index
    }</a
  ></HoverCard
>{/if
}{@render joined.end?.()}
